/* ─── Quiz data ─────────────────────────────────────────────── */
const QUESTIONS = [
  {
    id: "q1",
    text: "Which of the following are statically typed programming languages?",
    helpText: "Statically typed languages perform type checking at compile time rather than at runtime.",
    choices: ["Python", "Java", "JavaScript", "C++"],
    correct: [1, 3], // Java, C++
  },
  {
    id: "q2",
    text: "Which languages were primarily designed for web front-end development?",
    choices: ["JavaScript", "Go", "TypeScript", "Rust"],
    correct: [0, 2], // JavaScript, TypeScript
  },
  {
    id: "q3",
    text: "Which of the following languages use garbage collection for memory management?",
    choices: ["C", "Java", "C++", "Python"],
    correct: [1, 3], // Java, Python
  },
];

/* ─── State ─────────────────────────────────────────────────── */
let submitted = false;

/* ─── DOM helpers ───────────────────────────────────────────── */
const $ = (sel, ctx = document) => ctx.querySelector(sel);
const $$ = (sel, ctx = document) => [...ctx.querySelectorAll(sel)];

/* ─── Progress update ───────────────────────────────────────── */
function updateProgress() {
  const answered = QUESTIONS.filter(q =>
    $$(`input[name="${q.id}"]:checked`).length > 0
  ).length;
  const pct = Math.round((answered / QUESTIONS.length) * 100);
  $(".progress-fill").style.width = `${pct}%`;
  $(".progress-label").textContent = `${answered} of ${QUESTIONS.length} answered`;
}

/* ─── Validation ────────────────────────────────────────────── */
function validate() {
  let valid = true;
  QUESTIONS.forEach(q => {
    const checked = $$(`input[name="${q.id}"]:checked`);
    if (checked.length === 0) valid = false;
  });
  return valid;
}

/* ─── Score and reveal answers ──────────────────────────────── */
function scoreAndReveal() {
  let correct = 0;

  QUESTIONS.forEach(q => {
    const card = $(`#card-${q.id}`);
    const checkedValues = $$(`input[name="${q.id}"]:checked`).map(el => Number(el.value));
    const isCorrect =
      checkedValues.length === q.correct.length &&
      q.correct.every(v => checkedValues.includes(v));

    if (isCorrect) {
      correct++;
      card.classList.add("correct");
    } else {
      card.classList.add("incorrect");
    }

    // Mark every choice label
    $$(`label[data-question="${q.id}"]`).forEach(lbl => {
      const idx = Number(lbl.dataset.idx);
      const wasChecked = checkedValues.includes(idx);
      const isAnswer = q.correct.includes(idx);

      lbl.classList.add("disabled");

      if (isAnswer) {
        lbl.classList.add("correct-answer");
      } else if (wasChecked && !isAnswer) {
        lbl.classList.add("wrong-pick");
      }
    });
  });

  return correct;
}

/* ─── Show result panel ─────────────────────────────────────── */
function showResult(score) {
  const total = QUESTIONS.length;
  const pct = Math.round((score / total) * 100);
  const msgs = [
    { min: 0, label: "Keep practicing!", sub: "Review the answers below and try again." },
    { min: 34, label: "Good effort!", sub: "You got some right — review the answers and try again." },
    { min: 67, label: "Nice work!", sub: "You're getting the hang of it. One more try for a perfect score?" },
    { min: 100, label: "Perfect score! 🎉", sub: "You nailed every question. Outstanding knowledge!" },
  ];
  const msg = [...msgs].reverse().find(m => pct >= m.min);

  const result = $(".quiz-result");
  $(".result-score", result).textContent = `${score} / ${total}`;
  $(".result-label", result).textContent = msg.label;
  $(".result-sub", result).textContent = msg.sub;
  result.classList.add("visible");
  result.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

/* ─── Reset ─────────────────────────────────────────────────── */
function resetQuiz() {
  submitted = false;
  $$("input[type='checkbox']").forEach(cb => {
    cb.checked = false;
    cb.disabled = false;
  });
  $$(".form-field").forEach(f => f.classList.remove("correct", "incorrect"));
  $$(".choice-label").forEach(l => l.classList.remove("disabled", "correct-answer", "wrong-pick"));
  $(".quiz-result").classList.remove("visible");
  $(".validation-msg").classList.remove("visible");
  $(".progress-fill").style.width = "0%";
  $(".progress-label").textContent = `0 of ${QUESTIONS.length} answered`;
  window.scrollTo({ top: 0, behavior: "smooth" });
}

/* ─── Init ──────────────────────────────────────────────────── */
document.addEventListener("DOMContentLoaded", () => {
  const form = $(".quiz-form");

  form.addEventListener("change", () => {
    if (!submitted) {
      updateProgress();
      $(".validation-msg").classList.remove("visible");
    }
  });

  form.addEventListener("submit", e => {
    e.preventDefault();
    if (submitted) return;

    if (!validate()) {
      const msg = $(".validation-msg");
      msg.classList.add("visible");
      msg.scrollIntoView({ behavior: "smooth", block: "nearest" });
      return;
    }

    submitted = true;
    const score = scoreAndReveal();
    $(".progress-fill").style.width = "100%";
    $(".progress-label").textContent = `${QUESTIONS.length} of ${QUESTIONS.length} answered`;
    showResult(score);
  });

  $(".retry-btn").addEventListener("click", resetQuiz);
});

