  --color-success: #28a745;
  --color-error: #dc3545;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --shadow-card: 0 2px 12px rgba(0,0,0,0.07), 0 1px 3px rgba(0,0,0,0.05);
  --shadow-focus: 0 0 0 3px rgba(0, 113, 227, 0.25);
  --font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

body {
  font-family: var(--font);
  background: var(--color-bg);
  color: var(--color-text-primary);
  min-height: 100vh;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 48px 16px 80px;
}

.quiz-wrapper {
  width: 100%;
  max-width: 640px;
}

/* Header */
.quiz-header {
  margin-bottom: 36px;
}

.quiz-eyebrow {
  display: inline-block;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-accent);
  background: var(--color-accent-light);
  padding: 4px 10px;
  border-radius: 20px;
  margin-bottom: 14px;
}

.quiz-title {
  font-size: 30px;
  font-weight: 700;
  letter-spacing: -0.5px;
  color: var(--color-text-primary);
  line-height: 1.2;
  margin-bottom: 10px;
}

.quiz-subtitle {
  font-size: 15px;
  color: var(--color-text-secondary);
  line-height: 1.5;
}

/* Progress bar */
.quiz-progress {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 20px;
}

.progress-bar {
  flex: 1;
  height: 4px;
  background: var(--color-border);
  border-radius: 99px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: var(--color-accent);
  border-radius: 99px;
  transition: width 0.4s ease;
  width: 0%;
}

.progress-label {
  font-size: 12px;
  color: var(--color-text-secondary);
  white-space: nowrap;
}

/* Form */
.quiz-form {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* Question card */
.form-field {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 28px;
  box-shadow: var(--shadow-card);
  transition: border-color 0.2s;
}

.form-field:focus-within {
  border-color: var(--color-border-focus);
}

.question-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
}

.question-number {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--color-text-secondary);
}

.question-badge {
  font-size: 11px;
  font-weight: 500;
  color: var(--color-accent);
  background: var(--color-accent-light);
  padding: 2px 8px;
  border-radius: 99px;
}

.question-label {
  font-size: 17px;
  font-weight: 600;
  color: var(--color-text-primary);
  line-height: 1.4;
  margin-bottom: 6px;
  display: block;
}

.help-text {
  font-size: 13px;
  color: var(--color-text-help);
  line-height: 1.5;
  margin-bottom: 18px;
  display: flex;
  align-items: flex-start;
  gap: 6px;
}

.help-text svg {
  flex-shrink: 0;
  margin-top: 1px;
}

.choices {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 16px;
}

/* Custom checkbox option */
.choice-label {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s, box-shadow 0.15s;
  user-select: none;
  position: relative;
}

.choice-label:hover {
  border-color: var(--color-accent);
  background: var(--color-accent-light);
}

.choice-label:has(input:checked) {
  border-color: var(--color-accent);
  background: var(--color-accent-light);
}

.choice-label:has(input:focus-visible) {
  box-shadow: var(--shadow-focus);
  outline: none;
}

/* Visually hidden native checkbox */
.choice-label input[type="checkbox"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
  pointer-events: none;
}

.custom-checkbox {
  width: 20px;
  height: 20px;
  border: 2px solid var(--color-border);
  border-radius: 5px;
  background: #fff;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: border-color 0.15s, background 0.15s;
}

.choice-label:has(input:checked) .custom-checkbox {
  background: var(--color-check-bg);
  border-color: var(--color-check-bg);
}

.custom-checkbox svg {
  display: none;
}

.choice-label:has(input:checked) .custom-checkbox svg {
  display: block;
}

.choice-text {
  font-size: 15px;
  color: var(--color-text-primary);
  font-weight: 400;
  line-height: 1.4;
}

.choice-label:has(input:checked) .choice-text {
  font-weight: 500;
  color: var(--color-accent);
}

/* Submit button */
.quiz-footer {
  margin-top: 8px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.submit-btn {
  width: 100%;
  padding: 16px 24px;
  font-size: 16px;
  font-weight: 600;
  font-family: var(--font);
  color: #fff;
  background: var(--color-accent);
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
  letter-spacing: -0.1px;
  box-shadow: 0 2px 8px rgba(0,113,227,0.3);
}

.submit-btn:hover {
  background: var(--color-accent-hover);
  box-shadow: 0 4px 16px rgba(0,113,227,0.35);
}

.submit-btn:active {
  transform: scale(0.99);
}

.submit-btn:focus-visible {
  outline: none;
  box-shadow: var(--shadow-focus), 0 2px 8px rgba(0,113,227,0.3);
}

.submit-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

.validation-msg {
  font-size: 13px;
  color: var(--color-error);
  text-align: center;
  display: none;
  align-items: center;
  justify-content: center;
  gap: 5px;
}

.validation-msg.visible {
  display: flex;
}

/* Result overlay */
.quiz-result {
  display: none;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 40px 28px;
  box-shadow: var(--shadow-card);
  text-align: center;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.quiz-result.visible {
  display: flex;
}

.result-icon {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  background: var(--color-accent-light);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 4px;
}

.result-score {
  font-size: 36px;
  font-weight: 700;
  color: var(--color-text-primary);
  letter-spacing: -1px;
}

.result-label {
  font-size: 18px;
  font-weight: 600;
  color: var(--color-text-primary);
}

.result-sub {
  font-size: 14px;
  color: var(--color-text-secondary);
  max-width: 320px;
  line-height: 1.5;
}

.retry-btn {
  margin-top: 8px;
  padding: 12px 28px;
  font-size: 15px;
  font-weight: 600;
  font-family: var(--font);
  color: var(--color-accent);
  background: var(--color-accent-light);
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background 0.15s;
}

.retry-btn:hover {
  background: #d4e5f9;
}

.retry-btn:focus-visible {
  outline: none;
  box-shadow: var(--shadow-focus);
}

/* Correct/incorrect state after submission */
.form-field.correct {
  border-color: var(--color-success);
}

.form-field.incorrect {
  border-color: var(--color-error);
}

.question-result-badge {
  display: none;
  font-size: 12px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 99px;
  margin-left: auto;
}

.form-field.correct .question-result-badge {
  display: inline-block;
  color: var(--color-success);
  background: #eaf6ec;
}

.form-field.incorrect .question-result-badge {
  display: inline-block;
  color: var(--color-error);
  background: #fde8ea;
}

/* Disabled state post-submit */
.choice-label.disabled {
  cursor: default;
  pointer-events: none;
}

.choice-label.correct-answer {
  border-color: var(--color-success) !important;
  background: #eaf6ec !important;
}

.choice-label.correct-answer .custom-checkbox {
  background: var(--color-success);
  border-color: var(--color-success);
}

.choice-label.correct-answer .custom-checkbox svg {
  display: block;
}

.choice-label.wrong-pick {
  border-color: var(--color-error) !important;
  background: #fde8ea !important;
}

.choice-label.wrong-pick .custom-checkbox {
  background: var(--color-error);
  border-color: var(--color-error);
}

@media (max-width: 480px) {
  body {
    padding: 28px 12px 60px;
  }

  .quiz-title {
    font-size: 24px;
  }

  .form-field {
    padding: 20px 18px;
  }
}
